/**
 * Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, classes, resolveSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/avatar.module.css'

export interface AvatarGroupProps {
  /**
   * Avatars, in the order the app ranks them, all with the same `size`.
   */
  children: JSX.Element
  /**
   * Maximum number drawn; the rest become "+N", and omitting it draws all.
   */
  max?: number
  /**
   * The group’s accessible name, such as "Assignees" rather than "Avatars".
   */
  label: string
}

/** Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set. */
export default function AvatarGroup(given: AvatarGroupProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const childrenSlot = resolveSlot(
      () => props.children,
      (child) => ({ label: child.label ?? child.name }),
    )
    return (
      <div class={styles.group} role="group" aria-label={props.label}>
        {childrenSlot.take(props.max)}
        {props.max !== undefined && childrenSlot.slotted().count > props.max ? (
          <span
            class={classes(styles.avatar, styles.surplus)}
            data-size={childrenSlot.slotted().props.size ?? 'md'}
          >
            {`+${childrenSlot.slotted().count - props.max}`}
          </span>
        ) : null}
      </div>
    )
  })
}
